p('Word boundaries avoid matching the flu alias inside influence.','small')
code('best_doc = next(d for d in retrieved_docs\n                if d["doc_id"] == candidate_sentences[0]["doc_id"])\nbest_sentence_text = candidate_sentences[0]["text"]')
p('The answer source follows the selected sentence, even if it comes from a document other than the top-ranked passage.','small')
code('resolved_message = self.resolve_coreference(message, session)\nkb_result = self.knowledge_service.query(\n    resolved_message, context_entity=None)')
p('Context is introduced through an explicit pronoun resolution step, avoiding unconditional reuse of the previous entity.')
